package model; import java.io.*;import java.util.*;import model.annotation.*;import exception.*;public abstract class Account implements Serializable,Comparable<Account>{private static final long serialVersionUID=1L;private static long counter=1000;@Id private final String accountNumber;private String ownerName;@Positive private long balance;private boolean active=true;protected Account(String owner,long opening){if(opening<0)throw new IllegalArgumentException("Opening balance cannot be negative");accountNumber="AC"+(++counter);ownerName=Objects.requireNonNull(owner);balance=opening;}public String getAccountNumber(){return accountNumber;}public String getOwnerName(){return ownerName;}public synchronized long getBalance(){return balance;}public boolean isActive(){return active;}public synchronized void deposit(long amount)throws InvalidAmountException{if(amount<=0)throw new InvalidAmountException("Deposit must be positive");balance+=amount;}protected synchronized void changeBalance(long amount){balance+=amount;}public synchronized boolean withdraw(long amount)throws InsufficientFundsException,InvalidAmountException{if(amount<=0)throw new InvalidAmountException("Amount must be positive");if(!canWithdraw(amount))throw new InsufficientFundsException(Math.max(0,amount-balance));balance-=amount;return true;}public abstract double interestRate();public abstract boolean canWithdraw(long amount);public synchronized void transferTo(Account to,long amount)throws BankException,InvalidAmountException,InsufficientFundsException{if(to==null||to==this)throw new BankException("Invalid destination account");Account first=accountNumber.compareTo(to.accountNumber)<0?this:to,second=first==this?to:this;synchronized(first){synchronized(second){if(amount<=0)throw new InvalidAmountException("Amount must be positive");if(!canWithdraw(amount))throw new InsufficientFundsException(Math.max(0,amount-balance));balance-=amount;to.balance+=amount;}}}public int compareTo(Account a){return accountNumber.compareTo(a.accountNumber);}public String toString(){return accountNumber+" | "+ownerName+" | ₹"+balance+" | "+(active?"ACTIVE":"CLOSED");}public boolean equals(Object o){return o instanceof Account a&&accountNumber.equals(a.accountNumber);}public int hashCode(){return accountNumber.hashCode();}}
